<section class="panel auth-panel"><h2>Beschreibung und Tags</h2><form method="post" action="/catalog/save"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space_id']) ?>"><input type="hidden" name="entry" value="<?= $e($row['id']) ?>"><input type="hidden" name="entry_revision" value="<?= $e($data['submitted_entry_revision']??$row['revision']) ?>"><input type="hidden" name="catalog_revision" value="<?= $e($data['submitted_catalog_revision']??$data['catalog']['revision']) ?>">
<label for="catalog-description">Beschreibung</label><textarea id="catalog-description" name="description" rows="8" maxlength="16384" <?= $data['can_write']?'':'readonly' ?>><?= $e($data['catalog']['description']) ?></textarea><p class="field-note">UTF-8-Text bis 16 KiB. Ausgelesene Metadaten bleiben getrennt; Markup wird als Text behandelt.</p>
<fieldset class="tag-choices"><legend>Tags auswählen</legend><?php foreach($data['tags'] as$tag): ?><label class="checkbox-label"><input type="checkbox" name="tags[]" value="<?= $e($tag['id']) ?>" <?= in_array($tag['id'],$data['selected_tags'],true)?'checked':'' ?> <?= $data['can_write']?'':'disabled' ?>><?= $e($tag['name']) ?></label><?php endforeach ?><?php if($data['tags']===[]): ?><p class="subtle">Noch keine Tags in diesem Bereich.</p><?php endif ?></fieldset><p class="field-note">Bis zu 50 Tags je Datei auswählen. Ohne Auswahl werden alle Tags dieser Datei entfernt.</p>
<?php if($data['can_write']): ?><button class="button" type="submit">Beschreibung und Tags speichern</button><?php endif ?></form></section>
<?php if($data['can_manage_tags']): ?><details class="panel file-action"><summary>Tags dieses Bereichs verwalten</summary><div class="disclosure-content"><p>Umbenennen wirkt auf alle Referenzen dieses Tags. Löschen ist nur möglich, wenn der Tag auch im Papierkorb keiner Datei mehr zugeordnet ist.</p>
<?php foreach(['create'=>'Tag anlegen','rename'=>'Tag umbenennen','delete'=>'Unbenutzten Tag löschen']as$operation=>$label): ?><form class="settings-form" method="post" action="/catalog/tag"><h3><?= $e($label) ?></h3><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space_id']) ?>"><input type="hidden" name="entry" value="<?= $e($row['id']) ?>"><input type="hidden" name="operation" value="<?= $e($operation) ?>">
<?php if($operation!=='create'): ?><label for="tag-selection-<?= $e($operation) ?>">Tag</label><select id="tag-selection-<?= $e($operation) ?>" name="selection" required><option value="">Tag auswählen</option><?php foreach($data['tags'] as$tag): ?><option value="<?= $e($tag['id'].':'.$tag['revision']) ?>"><?= $e($tag['name']) ?></option><?php endforeach ?></select><?php endif ?>
<?php if($operation!=='delete'): ?><label for="tag-name-<?= $e($operation) ?>">Tagname</label><input id="tag-name-<?= $e($operation) ?>" name="name" required maxlength="80"><?php endif ?><label><input type="checkbox" name="confirm" value="1" required> Diese Tagänderung bestätigen.</label><button class="button button-outline" type="submit"><?= $e($label) ?></button></form><?php endforeach ?></div></details><?php endif ?>

